function taskListSyncNotice(){let html='';if(state.guestTasksPendingSync)html+='<div class="card small"><p>Some plans saved on this device have not been imported yet. <a class="link" href="guest-import.html">Review device plans</a></p></div>';if(taskListSyncError)html+='<div class="card" role="alert"><strong>Saved plans could not be refreshed.</strong><p>This view may be out of date. '+esc(taskListSyncError)+'</p><button type="button" class="btn secondary full" data-refresh-tasks>Retry task sync</button></div>';return html}
function validBreakdownResponse(result){if(!result||typeof result!=='object'||!Array.isArray(result.steps)||result.steps.length<3||result.steps.length>18)return false;const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;return result.steps.every(step=>step&&typeof step.text==='string'&&step.text.trim().length>0&&step.text.length<=280&&Number.isInteger(step.planned_minutes)&&step.planned_minutes>=1&&step.planned_minutes<=240)&&['template','ai'].includes(result.source)&&(result.template_id===null||typeof result.template_id==='string'&&uuid.test(result.template_id))&&(result.notice===null||typeof result.notice==='string')&&typeof result.prompt_version==='string'&&result.usage&&Number.isInteger(result.usage.used)&&result.usage.used>=0&&Number.isInteger(result.usage.limit)&&result.usage.limit>=0}function showPreloader(){if(page==='welcome')return;const app=$('#app');if(!app)return;app.inert=true;app.setAttribute('aria-busy','true');document.body.insertAdjacentHTML('beforeend',`<div class="preloader" id="preloader" role="status" aria-live="polite" aria-label="Kickoff is getting ready"><div class="preloader-panel"><span class="preloader-mark" aria-hidden="true">✦</span><strong>kickoff</strong><span class="preloader-message">Small steps. Steady progress.</span><div class="preloader-track" aria-hidden="true"><span></span></div></div></div>`);window.__kickoffBootTimer=setTimeout(hidePreloader,12000)}
function hidePreloader(){clearTimeout(window.__kickoffBootTimer);const app=$('#app'),loader=$('#preloader');app?.removeAttribute('inert');app?.removeAttribute('aria-busy');if(loader){loader.classList.add('is-hidden');setTimeout(()=>loader.remove(),360)}}
function startRewardCelebration(){
  if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
  const layer=document.createElement('div');
  layer.className='celebration-layer';
  layer.setAttribute('aria-hidden','true');
  const colors=['#d9a441','#f3d78a','#8caf7b','#ffffff','#dcb7cf'];
  const shapes=['is-star','is-diamond','is-dot'];
  for(let index=0;index<38;index++){
    const spark=document.createElement('span');
    spark.className=`celebration-spark ${shapes[Math.floor(Math.random()*shapes.length)]}`;
    spark.style.left=`${Math.random()*100}%`;
    spark.style.setProperty('--size',`${4+Math.random()*6}px`);
    spark.style.setProperty('--spark-color',colors[Math.floor(Math.random()*colors.length)]);
    spark.style.setProperty('--fall-time',`${2500+Math.random()*1000}ms`);
    spark.style.setProperty('--fall-delay',`${Math.random()*450}ms`);
    spark.style.setProperty('--drift',`${Math.round(Math.random()*140-70)}px`);
    spark.style.setProperty('--spin',`${Math.round(Math.random()*540-270)}deg`);
    layer.append(spark);
  }
  document.body.append(layer);
  window.setTimeout(()=>layer.remove(),4300);
}
window.addEventListener('error',hidePreloader,{once:true});window.addEventListener('unhandledrejection',hidePreloader,{once:true});function shell(content,{wide=false,nav=true,back=''}={}){const initial=state.name?esc(state.name.trim().charAt(0).toUpperCase()):'';return `<div class="app-layout"><header class="topline"><div class="topbar-inner"><a class="brand" href="home.html"><span class="brand-mark">✦</span><span>kickoff</span></a>${nav?navBar():''}${back?`<a class="link small header-back" href="${back}">← Back</a>`:state.name?`<div class="header-profile" aria-label="Profile: ${esc(state.name)}"><span class="profile-avatar" aria-hidden="true">${initial}</span><span class="profile-copy"><small>Your space</small><strong>${esc(state.name)}</strong></span></div>`:''}</div></header><main class="shell ${wide?'wide':''}">${content}</main><div id="toast" class="toast" role="status" aria-live="polite" hidden></div></div>`}
