const templates={Essay:[['Choose a prompt and gather materials',15],['Write a rough outline',15],['Draft the introduction',20],['Write one body section',20],['Review and tidy your draft',15]],'Lab report':[['Open your lab notes and rubric',10],['Organise results and observations',15],['Draft the methods section',20],['Write results and discussion',20],['Check references and formatting',15]],'Exam revision':[['Choose one topic to review',10],['Read your notes for that topic',15],['Make a few recall questions',15],['Try a short practice set',20],['Check answers and note gaps',10]],'Group project':[['Review the brief and shared notes',10],['List the next group deliverable',10],['Work on one small section',20],['Share a progress update',10]],Reading:[['Choose a short section',10],['Read with a few notes',20],['Write a one-sentence takeaway',5]],Presentation:[['Decide the main takeaway',10],['Make a simple slide outline',15],['Build the first few slides',20],['Practise the opening aloud',10]],'Video course':[['Find the next chapter or timestamp',5],['Watch the next 20 minutes',20],['Write one takeaway or question',5],['Save your timestamp for next time',5]]};
function templateLibraryPage(){const items=state.templateCatalog||[];return shell(`<a class="back" href="new-task.html">← Your task</a><div class="eyebrow">A gentle place to begin</div><h1>Ready-made plans</h1><p>Pick a starting point, then make it your own. ${state.templateManifest?.items?.length||0} plan types are available.</p><div class="template-library-grid">${items.length?items.map((item,i)=>`<a class="card template-library-card" href="template-detail.html?id=${encodeURIComponent(item.id)}"><span class="template-art" aria-hidden="true">${['✍️','🌿','📚','🧪','🗂️','🎤','☀️'][i%7]}</span><span class="badge">${esc(item.task_type.replaceAll('_',' '))}</span><h2>${esc(item.title)}</h2><p>${esc(item.language.toUpperCase())} · version ${item.version}</p><span class="link">View steps →</span></a>`).join(''):`<div class="card empty"><div class="empty-icon">🌱</div><h2>No plans found</h2><p>Try again in a moment, or start with your own task.</p><button class="btn secondary" data-reload-templates>Try again</button></div>`}</div><div class="template-garden-art" aria-hidden="true"><svg viewBox="0 0 320 120" role="img"><path d="M12 100h296" stroke="#cbdcc7" stroke-width="3" stroke-linecap="round"/><path d="M160 99V38m0 25c-34 0-47-16-46-34 22-2 40 8 46 34Zm0-11c1-22 15-35 38-39 2 20-9 34-38 39Z" fill="#83ad79" stroke="#47764b" stroke-width="3" stroke-linejoin="round"/><circle cx="160" cy="27" r="11" fill="#f4d385"/></svg></div>`,{wide:true,nav:true})}
function guestImportPage(){const plans=state.guestTasksBackup||[];return shell(`<a class="back" href="settings.html">← Settings</a><div class="eyebrow">Your plans, your choice</div><h1>Bring your saved plans along?</h1><p>These plans are still saved on this device. Import them to your signed-in account whenever you’re ready.</p><div class="card guest-import-card"><div class="guest-import-art" aria-hidden="true"><svg viewBox="0 0 190 140"><circle cx="95" cy="67" r="48" fill="#edf4e8"/><path d="M71 51h48v49H71z" fill="#fff" stroke="#6e9569" stroke-width="3"/><path d="M81 64h28m-28 11h28m-28 11h19" stroke="#a2bea0" stroke-width="3" stroke-linecap="round"/><path d="M49 108c15 8 28 12 46 12 19 0 33-5 48-14" fill="none" stroke="#88ad7e" stroke-width="3" stroke-linecap="round"/></svg></div><h2>${plans.length?`${plans.length} saved ${plans.length===1?'plan':'plans'}`:'No local plans waiting'}</h2>${plans.length?`<ul class="guest-import-list">${plans.slice(0,6).map(t=>`<li><span class="win-check" aria-hidden="true">${t.steps?.length||0}</span><strong>${esc(t.title)}</strong></li>`).join('')}${plans.length>6?`<li class="small">and ${plans.length-6} more</li>`:''}</ul><button class="btn primary full" data-import-guest>Import these plans</button>`:`<p>Everything is up to date.</p>`}<button class="btn quiet full" data-keep-guest>Keep these on this device for later</button><p class="small center" id="guest-import-feedback" role="status">Nothing is uploaded until you choose Import.</p></div>`,{nav:true})}
function tasksPage(){const requested=new URLSearchParams(location.search).get('status')||'all',allowed=['all','active','completed','archived'],filter=allowed.includes(requested)?requested:'all',rows=state.tasks.filter(t=>filter==='all'||(filter==='active'?(t.status|| (t.done?'completed':'active'))==='active':(t.status|| (t.done?'completed':'active'))===filter));return shell(`<div class="card-head"><div><div class="eyebrow">Your plans</div><h1 style="font-size:38px">Tasks</h1></div><a class="btn primary" href="new-task.html">＋ New</a></div>${taskListSyncNotice()}<div class="task-filter-tabs" aria-label="Filter tasks">${allowed.map(x=>`<a class="pill" href="tasks.html?status=${x}" ${filter===x?'aria-current="page"':''}>${x[0].toUpperCase()+x.slice(1)} <span>${x==='all'?state.tasks.length:state.tasks.filter(t=>(t.status||(t.done?'completed':'active'))===x).length}</span></a>`).join('')}</div>${rows.length?`<div class="card">${rows.map(taskRow).join('')}</div>`:`<div class="card empty"><div class="empty-icon">🪴</div><h2>${filter==='all'?'Nothing on the list yet':`No ${filter} plans`}</h2><p>${filter==='all'?'That’s a lovely place to begin. Add one thing you’d like to move forward.':'Your plans will show here when they reach this section.'}</p>${filter==='all'?'<a class="btn primary" href="new-task.html">Create a task</a>':''}</div>`}`,{nav:true})}
function templateDetailPage(){const item=state.selectedTemplate;if(!item)return shell(`<div class="card empty"><div class="empty-icon">🌱</div><h2>Choose a plan to view</h2><a class="btn primary" href="template-library.html">Browse plans</a></div>`,{nav:true});const variants=Object.keys(item.variants||{}),variant=state.selectedVariant&&item.variants?.[state.selectedVariant]?state.selectedVariant:variants.includes('standard')?'standard':variants[0],steps=item.variants?.[variant]?.steps||[];return shell(`<a class="back" href="template-library.html">← All plans</a><div class="template-detail-hero"><span class="template-art">🌼</span><span class="badge">${esc(item.task_type.replaceAll('_',' '))}</span><h1>${esc(item.title)}</h1><p>${esc(item.description||'A flexible plan you can adjust to fit your energy and time.')}</p></div><div class="field"><label for="template-variant">Choose how many steps feel right</label><select id="template-variant">${variants.map(v=>`<option value="${esc(v)}" ${variant===v?'selected':''}>${esc(v[0].toUpperCase()+v.slice(1))}</option>`).join('')}</select></div><ol class="template-preview-steps">${steps.map((s,i)=>`<li><span>${i+1}</span><div><strong>${esc(s.text)}</strong><small>${s.planned_minutes} min</small></div></li>`).join('')}</ol><button class="btn primary full" data-use-template>Use this plan <span aria-hidden="true">→</span></button><p class="small center">You can edit every step before saving.</p>`,{nav:true})}
async function loadTemplateCatalog(){const language=state.language||'en',query=new URLSearchParams({language,limit:'100'});let items=[],cursor=null,list;do{if(cursor)query.set('cursor',cursor);list=await publicRequest('/v1/templates?'+query.toString(),{cacheKey:cursor?undefined:'kickoff.templates.'+language});items.push(...(list.items||[]));cursor=list.next_cursor||null;query.delete('cursor')}while(cursor);state.templateCatalog=items;state.templateManifest=await publicRequest('/v1/templates/manifest',{cacheKey:'kickoff.template-manifest'});if(page==='template-detail'){const id=new URLSearchParams(location.search).get('id');if(id)state.selectedTemplate=await publicRequest('/v1/templates/'+encodeURIComponent(id),{cacheKey:'kickoff.template.'+id})}}
async function refreshServiceStatus(){const target=$('#service-status-results');if(!target)return;target.innerHTML=['App API','Sign-in service'].map(n=>`<div class="card status-item is-loading"><span class="status-dot"></span><div><strong>${n}</strong><small>Checking connection…</small></div><span class="status-pulse"></span></div>`).join('');const results=await Promise.allSettled([publicRequest('/v1/health'),publicRequest('/v1/health/ready')]);target.innerHTML=results.map((r,i)=>{const names=['App API','Sign-in service'],up=r.status==='fulfilled',detail=up?(r.value.status||r.value.message||'Available'):(r.reason?.message||'Unavailable');return `<div class="card status-item ${up?'is-up':'is-down'}"><span class="status-dot"></span><div><strong>${names[i]}</strong><small>${esc(detail)}</small></div><span class="status-state">${up?'Online':'Check connection'}</span></div>`}).join('')}
